/* The log2_exact descriptor: fixLog2Exact against MPFR at 256 bits.
 *
 * The hard-case points are the BaCSeL log2 list (test/data/hardcases/log2.txt,
 * BaCSeL sha e372414bc6af4a2911e07abe03de9854f32561fd), embedded here as a
 * static array because the sweep reads FIX_SOURCE_DIR and this card adds no
 * files beyond its NEW list. Values are the raw input column only; the binade
 * and midpoint-distance columns are not needed by the sweep.
 */
#include "../sweep.h"
#include "../data/libfixmath_edges.h"
#include "fixed/fixed_log.h"

static int64_t eval( int64_t a, int64_t b )
{
	( void )b;
	return fixLog2Exact( a );
}

static int64_t ref( int64_t a, int64_t b )
{
	( void )b;
	if ( a <= 0 )
	{
		return INT64_MIN; /* documented: no value there */
	}
	mpfr_t* v = sweep_mpfr_tmp();
	mpfr_set_si( *v, (long)a, MPFR_RNDN );
	mpfr_div_2ui( *v, *v, 16, MPFR_RNDN );
	mpfr_log2( *v, *v, MPFR_RNDN );
	return sweep_mpfr_round( *v );
}

static const sweep_piece pieces[] = {
	{ -4096, 1, 0, 0, 0, SWEEP_EXHAUSTIVE },
	{ 1, 1048577, 0, 0, 0, SWEEP_EXHAUSTIVE },
	{ 1048576, INT64_MAX, 0, 0, 262144, SWEEP_PER_BINADE },
};

